  (SELECT COUNT(*)
  FROM `vitis_vinifera_core_70_116_5`.gene n
  JOIN `vitis_vinifera_core_69_114_5`.gene o ON o.stable_id = n.stable_id
 WHERE n.is_current = 1 AND o.is_current = 1
   AND (n.description IS NULL OR n.description = '')
   AND o.description IS NOT NULL AND o.description <> '') AS rescuable_now,
  56 AS rescuable_at_generation;

SELECT 'zea_mays' AS production_name,
  (SELECT meta_value FROM `zea_mays_core_69_114_8`.meta WHERE meta_key='species.production_name' LIMIT 1) AS e114_name,
  (SELECT meta_value FROM `zea_mays_core_70_116_8`.meta WHERE meta_key='species.production_name' LIMIT 1) AS e116_name,
  (SELECT COUNT(*)
  FROM `zea_mays_core_70_116_8`.gene n
  JOIN `zea_mays_core_69_114_8`.gene o ON o.stable_id = n.stable_id
 WHERE n.is_current = 1 AND o.is_current = 1
   AND (n.description IS NULL OR n.description = '')
   AND o.description IS NOT NULL AND o.description <> '') AS rescuable_now,
  39746 AS rescuable_at_generation;

